import {W,setW,esc,dFR,dhFR,nb,nomP,uname,ukey,todayIso,api,toast,vcfg,profil,charteCur,charteSigOf,recsOf,openRec,manque,MANQ,saveDraft,saveDraftSoon,loadDraft,draftFor,sumHTML,diffHTML,wizHTML,start,ID,pl,zoneLab,ensureCss} from './reception.js';
import {daysSince,lacheRec,prisRec,prisOnly,pendingExits,contestOpen,contestsOpen,contreRec,redoAsked,swExit,swExitAny,swEntry,swForced,swEtat,swOpen,swDone,swLate,swStarted,swAttendu,mvCounters,mvHTML,mvLine,mvState,quiHTML,quiDocHTML,conducteursHTML,persHTML,mvViews,openMouv,histState,openHist,histHTML} from './mouvements.js'; /* 23/10 : 🕓 Historique */
if(typeof window!=='undefined')window.addEventListener('online',()=>{try{regFlush().catch(()=>{});}catch(e){}}); /* hors connexion : la remise attend sur l'appareil ; au retour du réseau elle part sans attendre le contrôle périodique */
/* ── état des écrans de ce fichier (pas dans le brouillon de l'assistant) ── */
const S2={view:null,label:'',sw:null,pad:null,refus:false,q:'',arb:null};
const RESP_POSTES=['gerant','dir_adjointe','dir_technique','resp_exploitation','resp_operations','conducteur','chef','resp_flotte'];
const isResp=p=>!!p&&(p.admin||RESP_POSTES.includes(p.poste));
const mgrOf=(me,ctx)=>!!(me&&me.admin)||!!(ctx&&ctx.can&&ctx.can('flotte.manage'));
const srvMgr=(me,ctx)=>mgrOf(me,ctx)||isResp(me); /* ≈ rôle serveur chef / bureau (registre_set) : peut écrire la clé « switch » et les décisions */
const canValidate=(me,ctx,r)=>mgrOf(me,ctx)||!!(r&&r.aValider&&me&&r.aValider.par===me.id)||!!(r&&r.switchId&&me&&isResp(me));
const canArb=(me,ctx,r)=>mgrOf(me,ctx)||!!(r&&r.contest&&me&&(r.contest.resp||[]).some(x=>x&&x.key===me.id))||!!(me&&isResp(me)&&me.poste==='resp_flotte');
const seulW=w=>!!w&&(w.qui==='seul'||!!w.lache||!!w.memoire||!!w.contreDe);
const people=ctx=>(ctx&&ctx.people||[]).filter(p=>p&&p.id&&(p.active!==false||p.invite));
const laisses=me=>vehAll().filter(v=>v.laisse&&!v.conducteurKey&&!v.conducteur&&(!v.laisse.aKey||(me&&v.laisse.aKey===me.id))); /* à prendre : laissés « à qui le prendra », et ceux laissés à moi */
const mienV=(v,me)=>!!v&&!!me&&((v.conducteurKey&&v.conducteurKey===me.id)||(!v.conducteurKey&&!!me._acc&&vehDe(me._acc).some(x=>x.immat===v.immat))); /* mon véhicule (clé, ou nom libre de l'import) */
const mine=me=>vehAll().filter(v=>mienV(v,me));
/* 23/10 (Ethan : « j'ai enlevé le Sprinter de Sofiane pour Nadir : ça dit que son état des lieux est attendu mais ça ne lui propose pas de le faire ») : un véhicule venu de
   l'import porte un NOM de conducteur sans clé → le changement déclaré ne reconnaissait pas l'ancien conducteur connecté. Ici : même nom (mots dans n'importe quel ordre). */
const sameName=(a,b)=>{const n=s=>String(s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').trim().toLowerCase().split(/\s+/).filter(Boolean).sort().join(' ');const x=n(a),y=n(b);return !!x&&x===y;};
const keyOfName=(nom,ctx)=>{if(!nom)return '';const P=people(ctx).filter(p=>sameName(nomP(p),nom));return P.length===1?P[0].id:'';}; /* un seul homonyme possible, sinon on ne devine pas */
const meNom=me=>me?((me._acc&&me._acc.name)||nomP(me)||me.name||''):'';
const isAncien=(v,me)=>{const sw=v&&v.switch;if(!sw||!sw.ancien||!me)return false;if(sw.ancien.key)return sw.ancien.key===me.id;return sameName(sw.ancien.nom,meNom(me));};
const today=()=>todayIso();
// véhicule attitré (nom ou clé) sans aucun état des lieux pour son conducteur (ni le sien, ni une signature « exact » sur la sortie d'un collègue), ni laissé, ni en changement
export function sansEdl(v){if(!v||v.laisse||swOpen(v)||(!v.conducteur&&!v.conducteurKey))return false;if(prisRec(v))return false;return !recsOf(v.immat).some(r=>r.type==='reception'&&!r.remplacePar&&(!v.conducteurKey||!r.conducteurKey||r.conducteurKey===v.conducteurKey));}
const edl1Ref=()=>{const C=vcfg()||{};return C.premierAt||C.at||null;};
const edl1Sev=v=>{const j=daysSince(edl1Ref());return (v&&v.edl1Relance)||j>=14?'bad':j>=7?'warn':'info';};
/* ── le chantier du jour d'une personne (planning) et son chef : validateur par défaut, responsables à alerter ── */
function siteDuJour(me,ctx){try{const t=today();const PL=espacePlanning()||{};const aff=(((PL[weekKey(t)]||{}).aff||{})[me.id])||{};const ids=aff[t]||[];const sites=(ctx.api&&ctx.api.sites&&ctx.api.sites())||[];for(const id of ids){const c=sites.find(s=>s&&s.id===id);if(c)return c;}return ids.length?{id:ids[0],name:String(ids[0])}:null;}catch(e){return null;}}
const validators=ctx=>people(ctx).filter(isResp).sort((a,b)=>nomP(a).localeCompare(nomP(b)));
function defaultValidator(me,ctx){const P=validators(ctx).filter(p=>p.id!==me.id);const c=siteDuJour(me,ctx);let p=null;
  if(c){p=P.find(x=>x.id===c.chef)||P.find(x=>x.id===c.conducteur)||null;}
  if(!p)p=P.find(x=>x.poste==='resp_flotte')||P.find(x=>x.poste==='resp_exploitation')||P.find(x=>x.admin)||P[0]||null;
  return p?{key:p.id,nom:nomP(p),poste:POSTES[p.poste]||''}:null;}
// responsables alertés quand un mouvement est contesté : responsable flotte + chef du chantier du jour + conducteur de travaux du chantier (sinon : responsable d'exploitation, administrateur)
function respAlerte(me,ctx){const P=validators(ctx);const out=[];const add=p=>{if(p&&p.id!==me.id&&!out.some(x=>x.key===p.id))out.push({key:p.id,nom:nomP(p),poste:POSTES[p.poste]||''});};
  P.filter(x=>x.poste==='resp_flotte').forEach(add);const c=siteDuJour(me,ctx);if(c){add(P.find(x=>x.id===c.chef));add(P.find(x=>x.id===c.conducteur));}
  if(!out.length){add(P.find(x=>x.poste==='resp_exploitation'));add(P.find(x=>x.admin));}return out;}
/* ── hôte des écrans : Parc (responsable flotte) ou Moi (conducteur, chef sans droit « Flotte ») ── */
function openX(k,label,me,ctx){if(mgrOf(me,ctx)){ctx.go('x:'+ID+':'+k);return;}S2.view=k;S2.label=label||'Véhicule';ctx.sub('vx');}
const wizLabel=w=>!w?'Véhicule':w.lache?'Je laisse le véhicule':w.contreDe?'Contre-état des lieux':w.type==='reception'?'Mon état des lieux':'Ma restitution';
export function openWiz(ctx){const w=W;if(!w)return;if(w.host==='moi'){S2.view='wiz';S2.label=wizLabel(w);ctx.sub('vx');}else ctx.go('x:'+ID+':wiz');}
export function home(me,ctx){S2.view=null;S2.pad=null;S2.refus=false;S2.arb=null;if(W&&W.host!=='moi'){const b=document.querySelector('#eq-app .ac-back[data-act="xsub"]');if(b){b.click();return;}}if(mgrOf(me,ctx)&&(!W||W.host!=='moi')){ctx.go('flotte');return;}ctx.sub('moi');}
/* ── étapes selon le mode (l'ordre d'origine est gardé ; « qui » devant, « cond » et « permis » sautés quand ça n'a pas de sens) ── */
export function stepsFor(w){if(!w)return [];if(w.lache)return ['a','ou','km','photos','inv','recap']; /* laisser un véhicule : à qui et quand, où, km et carburant, photos, inventaire, récapitulatif signé */
  const qui=w.v2&&!w.memoire&&!w.contreDe?['qui']:[];
  if(w.type==='restitution')return qui.concat(['releves','controles','photos','inv','cartes','recap']);
  const S=qui.slice();if(!w.self)S.push('cond');if(!w.premier&&!w.contreDe)S.push('permis');S.push('releves','controles','photos','inv','cartes');
  const v=vehGet(w.vehId);const {charte:type}=profil(v||{});const ch=charteCur(type);if(!((w.premier||w.contreDe)&&(!ch||charteSigOf(w.cond&&w.cond.key,type))))S.push('charte'); /* premier état des lieux, contre-état des lieux : charte déjà signée → rien à re-signer */
  if(w.contreDe)S.push('ecarts');S.push('recap');return S;}
export const STEP_T2={qui:'Qui est là ?',ou:'Où est le véhicule ?',km:'Kilométrage et carburant',a:'À qui et quand ?',ecarts:'Écarts constatés'};
const CARB_DEF=['Réserve','1/4','1/2','3/4','Plein'];
const carbRel=()=>(((vcfg()||{}).edl||{}).releves||[]).find(x=>x.type==='choix'&&/carbur/i.test(x.id+' '+x.label))||null;
export const ouLabel=w=>{const o=(w&&w.ou)||{};const t=String(o.txt||'').trim();return o.k==='depot'?'Dépôt'+(t?' · '+t:''):o.k==='chantier'?String(o.site||'Chantier')+(t?' · '+t:''):t;};
const pick2=(P,q,act,cur)=>{const L=P.filter(p=>!q||nomP(p).toLowerCase().includes(q)).slice(0,60);return L.map(p=>`<button class="veh-pick${cur===p.id?' on':''}" data-act="x" data-v="veh|${act}|${esc(p.id)}"><b>${esc(nomP(p))}</b><small>${esc(POSTES[p.poste]||'')}</small></button>`).join('')||'<div class="eq-s">Personne ne correspond.</div>';};
const aMode=w=>w.aMode||(w.a?'pers':'libre');
const toLab=w=>w.a?w.a.nom:'qui le prendra';
// écarts chiffrés entre le contre-état des lieux en cours et ce que l'autre a déclaré (km, manquants, impacts, photos) — en plus du texte libre
function ecartsAuto(x){const L=[];if(!x||!W)return L;const km=W.edl.km;const xk=x.edl&&x.edl.km;if(km!==''&&km!==null&&xk!==null&&xk!==undefined&&+km!==+xk)L.push('Kilométrage : '+nb(km)+' km au compteur, '+nb(xk)+' km déclarés ('+(+km>+xk?'+':'')+nb(+km-+xk)+' km)');
  const xm=(x.inventaire&&x.inventaire.miss)||{};const items=(x.inventaire&&x.inventaire.items)||[];Object.keys(W.inv.miss||{}).forEach(id=>{if(!xm[id])L.push('Manquant non déclaré : '+(((items.find(i=>i[0]===id)||[])[1])||id));});
  const xi=(x.edl&&x.edl.impacts||[]).length;if(W.edl.impacts.length>xi)L.push((W.edl.impacts.length-xi)+' impact'+(W.edl.impacts.length-xi>1?'s':'')+' de plus que déclaré'+(xi?' ('+xi+' déclaré'+(xi>1?'s':'')+')':''));
  const xp=Object.keys((x.edl&&x.edl.photos)||{}).length;if(!xp)L.push('Aucune photo dans son état des lieux');return L;}
