    <div class="veh-cols"><div><h3 style="margin:8px 0 4px">État des lieux de ${esc(X)} <span class="hint">· laissé le ${dFR(r.lache&&r.lache.at||r.at)} · ${esc(r.lache&&r.lache.ou||'')}</span></h3>${recapEdlHTML(r,false)}<button class="btn sm" data-act="x" data-v="veh|print|${esc(r.id)}">🖨 PDF</button></div>
      <div><h3 style="margin:8px 0 4px">Contre-état des lieux de ${esc(Y)} <span class="hint">· le ${dFR(c?c.at:r.contest.at)}</span></h3>${c?recapEdlHTML(c,false)+`<div class="veh-ko">« ${esc(c.ecarts||r.contest.motif||'')} »</div><button class="btn sm" data-act="x" data-v="veh|print|${esc(c.id)}">🖨 PDF</button>`:`<div class="veh-ko">« ${esc(r.contest.motif||'')} »</div>`}</div></div>
