/* référence d'une sortie (restitution, laisser) : la dernière entrée du conducteur concerné — son état des lieux, ou sa signature « exact » sur la sortie d'un collègue */
export function refFor(v,o){o=o||{};const key=o.cond&&o.cond.key;if(key){const r=recsOf(v.immat).find(r=>!r.remplacePar&&((r.type==='reception'&&r.conducteurKey===key)||(r.type==='restitution'&&r.lache&&r.pris&&r.pris.par===key)));if(r)return r;}return openRec(v)||prisRec(v);}
